function run(input: Input, context: Context): Output
  local n: number = input.number
  if n < 1 or n > 3999 or math.floor(n) ~= n then
    return { error = "out_of_range", message = "number must be an integer in 1..3999" }
  end

  local thou = {"", "M", "MM", "MMM"}
  local hund = {"", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"}
  local ten = {"", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"}
  local one = {"", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"}

  local t = thou[math.floor(n / 1000) + 1]
  local h = hund[math.floor((n % 1000) / 100) + 1]
  local te = ten[math.floor((n % 100) / 10) + 1]
  local o = one[(n % 10) + 1]

  local roman: string = t .. h .. te .. o
  return { roman = roman }
end

