function run(input: Input, context: Context): Output
    -- If running in a workflow-only scenario, tools may be unavailable. Guard immediately and return a clear error.
    if tools == nil then
        return {
            read = {
                error = "workflow_only",
                message = "Workflow-only environment: tools are not available."
            }
        }
    end

    local function to_number(v: any): number?
        if type(v) == "number" then
            return v
        end
        if type(v) == "string" then
            local n = tonumber(v)
            return n
        end
        return nil
    end

    -- Read price from input; external market/telegram tools are not available in this environment
    local price = to_number(input.price)
    if price == nil then
        return {
            read = {
                error = "missing_price",
                message = "No price provided. Supply input.price (number or numeric string)."
            }
        }
    end

    local threshold = to_number(input.threshold) or 100000
    local now = tools.time.now_utc({})

    if price > threshold then
        local chat_id = input.telegram_chat_id or input.chat_id or "unknown"
        local text = "BTC price " .. tostring(price) .. " at " .. now .. " exceeds threshold " .. tostring(threshold)
        local payload = { chat_id = chat_id, text = text, price = price, time = now }
        -- Cannot actually send because no Telegram/send tool is provided. Return payload and a recoverable error.
        return {
            read = {
                error = "no_telegram_tool",
                message = "Telegram send tool not available. Prepared payload but did not send.",
                would_notify = true,
                payload = payload
            }
        }
    end

    return {
        read = {
            notified = false,
            reason = "price_below_threshold",
            price = price,
            threshold = threshold,
            time = now
        }
    }
end

function run(input: Input, context: Context): Output
    local values = input.values or {}
    local seen: { [string]: boolean } = {}
    local unique: { string } = {}

    for i = 1, #values do
        local v = values[i]
        if not seen[v] then
            seen[v] = true
            table.insert(unique, v)
        end
    end

    table.sort(unique, function(a: string, b: string)
        return a < b
    end)

    return { values = unique }
end

